// Package config contains the agent's on-disk configuration schema and the
// validation rules that protect the OPNsense firewall from dangerous values.
//
// The configuration is generated by the os-pangolin OPNsense plugin and is
// never edited by the agent. Secrets are therefore only ever read from a file
// with mode 0600; they are never accepted on the command line (where they
// would be visible in ps(1)) and never written to logs or status files.
package config

import (
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"net/url"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"runtime"
	"strings"
	"time"
)

const (
	ModeSite   = "site"
	ModeClient = "client"

	DefaultStateDir  = "/var/db/pangolin"
	DefaultRunDir    = "/var/run"
	DefaultClientIf  = "pangolin0"
	DefaultSiteIf    = "newt0"
	DefaultMTU       = 1280
	DefaultSiteMTU   = 1420
	DefaultDNSOutput = "dns-records.json"

	SubnetRouterOPNsense = "opnsense"
	SubnetRouterPF       = "pf"
	SubnetRouterNone     = "none"
)

var (
	interfaceRE = regexp.MustCompile(`^[A-Za-z0-9_]{1,15}$`)
	hookRoots   = []string{
		"/usr/local/etc/pangolin",
		"/usr/local/opnsense/scripts/OPNsense/Pangolin",
	}
)

// Config is the top-level JSON document written by the plugin.
type Config struct {
	Mode              string              `json:"mode"`
	LogLevel          string              `json:"logLevel"`
	StateDir          string              `json:"stateDir"`
	HookScript        string              `json:"hookScript"`
	AllowInsecureHTTP bool                `json:"allowInsecureHttp,omitempty"`
	Site              *SiteConfig         `json:"site,omitempty"`
	Client            *ClientConfig       `json:"client,omitempty"`
	SubnetRouter      *SubnetRouterConfig `json:"subnetRouter,omitempty"`
	DNS               *DNSConfig          `json:"dns,omitempty"`
	HA                *HAConfig           `json:"ha,omitempty"`
}

type SiteConfig struct {
	Endpoint string `json:"endpoint"`
	ID       string `json:"id"`
	Secret   string `json:"secret"`
	Name     string `json:"name,omitempty"`

	MTU                     int    `json:"mtu"`
	InterfaceName           string `json:"interfaceName"`
	UseNativeMainInterface  bool   `json:"useNativeMainInterface"`
	UseNativeClientInterface bool  `json:"useNativeClientInterface"`
	DisableSSH              bool   `json:"disableSsh"`
	DisableClients          bool   `json:"disableClients"`
	PingInterval            string `json:"pingInterval"`
	PingTimeout             string `json:"pingTimeout"`
	LogLevel                string `json:"logLevel,omitempty"`
}

type ClientConfig struct {
	Endpoint string `json:"endpoint"`
	ID       string `json:"id"`
	Secret   string `json:"secret"`
	OrgID    string `json:"orgId,omitempty"`

	MTU           int      `json:"mtu"`
	InterfaceName string   `json:"interfaceName"`
	DNS           string   `json:"dns,omitempty"`
	UpstreamDNS   []string `json:"upstreamDns,omitempty"`
	PingInterval  string   `json:"pingInterval"`
	PingTimeout   string   `json:"pingTimeout"`
	LogLevel      string   `json:"logLevel,omitempty"`

	Holepunch                         bool `json:"holepunch"`
	PreferLocalRoutes                 bool `json:"preferLocalRoutes"`
	DisableRoutesAndAliasesOnExitNode bool `json:"disableRoutesAndAliasesOnExitNode"`
	// OverrideDNS must stay false on OPNsense: Unbound owns port 53. The
	// plugin integrates aliases through Unbound's include mechanism instead.
	OverrideDNS bool `json:"overrideDns"`
}

type SubnetRouterConfig struct {
	Enabled      bool     `json:"enabled"`
	Backend      string   `json:"backend"`
	LocalNetworks []string `json:"localNetworks"`
	NAT          bool     `json:"nat"`
	Firewall     bool     `json:"firewall"`
}

type DNSConfig struct {
	Enabled      bool     `json:"enabled"`
	SyncInterval string   `json:"syncInterval"`
	OutputFile   string   `json:"outputFile"`
	// ForwardDomains is an optional list of private DNS suffixes that should
	// be conditionally forwarded to the machine-client DNS proxy. Static alias
	// records are always published independently of this list.
	ForwardDomains []string `json:"forwardDomains,omitempty"`
	TTL            int      `json:"ttl"`
}

type HAConfig struct {
	Enabled       bool   `json:"enabled"`
	Interface     string `json:"interface"`
	RequiredState string `json:"requiredState"`
}

// Default returns a configuration with safe defaults. The plugin always sets
// these explicitly, but defaults make `pangolin-agent validate` useful and
// keep hand-written development configs predictable.
func Default() *Config {
	return &Config{
		Mode:     ModeClient,
		LogLevel: "info",
		StateDir: DefaultStateDir,
		Site: &SiteConfig{
			MTU:            DefaultSiteMTU,
			InterfaceName:  DefaultSiteIf,
			DisableSSH:     true,
			DisableClients: true,
			PingInterval:   "15s",
			PingTimeout:    "7s",
		},
		Client: &ClientConfig{
			MTU:           DefaultMTU,
			InterfaceName: DefaultClientIf,
			PingInterval:  "5s",
			PingTimeout:   "5s",
			Holepunch:     true,
		},
		SubnetRouter: &SubnetRouterConfig{
			Backend: SubnetRouterOPNsense,
			NAT:     true,
			Firewall: true,
		},
		DNS: &DNSConfig{
			SyncInterval: "15s",
			TTL:          60,
		},
		HA: &HAConfig{
			RequiredState: "MASTER",
		},
	}
}

// Load reads path, applies defaults and validates the result. The file must
// not be readable by group or other (mode 0600 or stricter).
func Load(path string) (*Config, error) {
	if path == "" {
		return nil, fmt.Errorf("config path is required")
	}
	info, err := os.Stat(path)
	if err != nil {
		return nil, fmt.Errorf("stat config: %w", err)
	}
	if runtime.GOOS != "windows" && info.Mode().Perm()&0o077 != 0 {
		return nil, fmt.Errorf("config %s has insecure permissions %04o; expected 0600", path, info.Mode().Perm())
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read config: %w", err)
	}
	cfg := Default()
	dec := json.NewDecoder(strings.NewReader(string(data)))
	dec.DisallowUnknownFields()
	if err := dec.Decode(cfg); err != nil {
		return nil, fmt.Errorf("parse config: %w", err)
	}
	cfg.ApplyDefaults()
	if err := cfg.Validate(); err != nil {
		return nil, err
	}
	return cfg, nil
}

func (c *Config) ApplyDefaults() {
	d := Default()
	if c.Mode == "" {
		c.Mode = d.Mode
	}
	if c.LogLevel == "" {
		c.LogLevel = d.LogLevel
	}
	if c.StateDir == "" {
		c.StateDir = d.StateDir
	}
	if c.Site == nil {
		c.Site = d.Site
	} else {
		if c.Site.MTU == 0 {
			c.Site.MTU = d.Site.MTU
		}
		if c.Site.InterfaceName == "" {
			c.Site.InterfaceName = d.Site.InterfaceName
		}
		if c.Site.PingInterval == "" {
			c.Site.PingInterval = d.Site.PingInterval
		}
		if c.Site.PingTimeout == "" {
			c.Site.PingTimeout = d.Site.PingTimeout
		}
	}
	if c.Client == nil {
		c.Client = d.Client
	} else {
		if c.Client.MTU == 0 {
			c.Client.MTU = d.Client.MTU
		}
		if c.Client.InterfaceName == "" {
			c.Client.InterfaceName = d.Client.InterfaceName
		}
		if c.Client.PingInterval == "" {
			c.Client.PingInterval = d.Client.PingInterval
		}
		if c.Client.PingTimeout == "" {
			c.Client.PingTimeout = d.Client.PingTimeout
		}
	}
	if c.SubnetRouter == nil {
		c.SubnetRouter = d.SubnetRouter
	}
	if c.SubnetRouter.Backend == "" {
		c.SubnetRouter.Backend = d.SubnetRouter.Backend
	}
	if c.DNS == nil {
		c.DNS = d.DNS
	}
	if c.DNS.SyncInterval == "" {
		c.DNS.SyncInterval = d.DNS.SyncInterval
	}
	if c.DNS.TTL == 0 {
		c.DNS.TTL = d.DNS.TTL
	}
	if c.DNS.OutputFile == "" {
		c.DNS.OutputFile = path.Join(c.StateDir, DefaultDNSOutput)
	}
	if c.HA == nil {
		c.HA = d.HA
	}
	if c.HA.RequiredState == "" {
		c.HA.RequiredState = d.HA.RequiredState
	}
}

// Validate enforces the security invariants the plugin promises to the
// operator. In particular it refuses default routes and wildcard local
// networks: a subnet router must never expose every VLAN or replace the
// default route.
func (c *Config) Validate() error {
	var errs []error
	add := func(format string, args ...any) { errs = append(errs, fmt.Errorf(format, args...)) }

	switch c.Mode {
	case ModeSite, ModeClient:
	default:
		add("mode must be %q or %q, got %q", ModeSite, ModeClient, c.Mode)
	}
	if !validLogLevel(c.LogLevel) {
		add("invalid logLevel %q", c.LogLevel)
	}
	if !isAbsPath(c.StateDir) {
		add("stateDir must be absolute, got %q", c.StateDir)
	}
	if c.HookScript != "" {
		if !isAbsPath(c.HookScript) {
			add("hookScript must be absolute")
		} else if !underAnyRoot(c.HookScript, hookRoots) {
			add("hookScript must live under /usr/local/etc/pangolin or the plugin script directory")
		}
	}

	if c.Mode == ModeSite {
		if c.Site == nil {
			add("site configuration is missing")
		} else {
			validateEndpoint(c.Site.Endpoint, c.AllowInsecureHTTP, "site.endpoint", add)
			validateSecret(c.Site.ID, "site.id", add)
			validateSecret(c.Site.Secret, "site.secret", add)
			validateInterface(c.Site.InterfaceName, "site.interfaceName", add)
			validateMTU(c.Site.MTU, "site.mtu", add)
			validateDuration(c.Site.PingInterval, "site.pingInterval", add)
			validateDuration(c.Site.PingTimeout, "site.pingTimeout", add)
		}
	}

	if c.Mode == ModeClient {
		if c.Client == nil {
			add("client configuration is missing")
		} else {
			validateEndpoint(c.Client.Endpoint, c.AllowInsecureHTTP, "client.endpoint", add)
			validateSecret(c.Client.ID, "client.id", add)
			validateSecret(c.Client.Secret, "client.secret", add)
			validateInterface(c.Client.InterfaceName, "client.interfaceName", add)
			validateMTU(c.Client.MTU, "client.mtu", add)
			validateDuration(c.Client.PingInterval, "client.pingInterval", add)
			validateDuration(c.Client.PingTimeout, "client.pingTimeout", add)
			if c.Client.DNS != "" && net.ParseIP(c.Client.DNS) == nil {
				add("client.dns must be an IP address, got %q", c.Client.DNS)
			}
			for _, s := range c.Client.UpstreamDNS {
				host := s
				if strings.Contains(s, ":") {
					h, _, err := net.SplitHostPort(s)
					if err != nil {
						add("client.upstreamDns %q is not host:port", s)
						continue
					}
					host = h
				}
				if net.ParseIP(host) == nil {
					add("client.upstreamDns %q is not an IP address", s)
				}
			}
			if c.Client.OverrideDNS {
				add("client.overrideDns must be false on OPNsense; use the Unbound integration instead")
			}
		}

		if c.SubnetRouter != nil {
			switch c.SubnetRouter.Backend {
			case SubnetRouterOPNsense, SubnetRouterPF, SubnetRouterNone:
			default:
				add("subnetRouter.backend must be opnsense, pf or none")
			}
			if c.SubnetRouter.Enabled {
				if len(c.SubnetRouter.LocalNetworks) == 0 {
					add("subnetRouter.localNetworks must not be empty when the subnet router is enabled")
				}
				for _, n := range c.SubnetRouter.LocalNetworks {
					validateLocalNetwork(n, add)
				}
				if c.Mode != ModeClient {
					add("subnetRouter is only valid in client mode")
				}
			}
		}

		if c.DNS != nil && c.DNS.Enabled {
			validateDuration(c.DNS.SyncInterval, "dns.syncInterval", add)
			if c.DNS.TTL < 0 || c.DNS.TTL > 86400 {
				add("dns.ttl must be between 0 and 86400")
			}
			if !isAbsPath(c.DNS.OutputFile) {
				add("dns.outputFile must be absolute")
			} else if !underAnyRoot(c.DNS.OutputFile, []string{c.StateDir}) {
				add("dns.outputFile must be inside stateDir")
			}
			for _, d := range c.DNS.ForwardDomains {
				if err := validateDomainSuffix(d); err != nil {
					add("dns.forwardDomains: %v", err)
				}
			}
		}
	}

	if c.HA != nil && c.HA.Enabled {
		validateInterface(c.HA.Interface, "ha.interface", add)
		switch strings.ToUpper(c.HA.RequiredState) {
		case "MASTER", "BACKUP":
		default:
			add("ha.requiredState must be MASTER or BACKUP")
		}
	}

	return errors.Join(errs...)
}

func (c *Config) StatePath() string {
	return filepath.Join(c.StateDir, c.Mode+"-status.json")
}

func (c *Config) PIDPath() string {
	return filepath.Join(DefaultRunDir, "pangolin_"+c.Mode+".pid")
}

func validLogLevel(s string) bool {
	switch strings.ToLower(s) {
	case "debug", "info", "warn", "warning", "error", "fatal":
		return true
	}
	return false
}

func validateEndpoint(raw string, allowHTTP bool, field string, add func(string, ...any)) {
	if strings.TrimSpace(raw) != raw || raw == "" {
		add("%s must be a non-empty URL without surrounding whitespace", field)
		return
	}
	u, err := url.Parse(raw)
	if err != nil || u.Host == "" {
		add("%s is not a valid URL: %q", field, raw)
		return
	}
	if u.User != nil {
		add("%s must not contain credentials in the URL", field)
	}
	switch u.Scheme {
	case "https":
	case "http":
		if !allowHTTP {
			add("%s must use https (set allowInsecureHttp only for isolated testing)", field)
		}
	default:
		add("%s must use https, got scheme %q", field, u.Scheme)
	}
	if strings.ContainsAny(raw, "\r\n") {
		add("%s must not contain newlines", field)
	}
}

func validateSecret(s, field string, add func(string, ...any)) {
	if strings.TrimSpace(s) == "" {
		add("%s must not be empty", field)
		return
	}
	if len(s) > 4096 {
		add("%s is implausibly long", field)
	}
	if strings.ContainsAny(s, "\r\n\x00") {
		add("%s contains control characters", field)
	}
}

func validateInterface(s, field string, add func(string, ...any)) {
	if !interfaceRE.MatchString(s) {
		add("%s must match [A-Za-z0-9_]{1,15}, got %q", field, s)
	}
}

func validateMTU(mtu int, field string, add func(string, ...any)) {
	if mtu < 576 || mtu > 9000 {
		add("%s must be between 576 and 9000, got %d", field, mtu)
	}
}

func validateDuration(s, field string, add func(string, ...any)) {
	d, err := time.ParseDuration(s)
	if err != nil {
		add("%s is not a duration: %q", field, s)
		return
	}
	if d < time.Second || d > 24*time.Hour {
		add("%s must be between 1s and 24h", field)
	}
}

// validateLocalNetwork rejects networks that would either expose everything
// (0.0.0.0/0, very broad prefixes) or are not unicast IPv4.
func validateLocalNetwork(cidr string, add func(string, ...any)) {
	ip, ipNet, err := net.ParseCIDR(strings.TrimSpace(cidr))
	if err != nil {
		add("subnetRouter.localNetworks: invalid CIDR %q", cidr)
		return
	}
	if ip.To4() == nil {
		add("subnetRouter.localNetworks: only IPv4 is supported, got %q", cidr)
		return
	}
	ones, bits := ipNet.Mask.Size()
	if bits != 32 || ones < 8 {
		add("subnetRouter.localNetworks: %q is too broad; use a prefix between /8 and /32", cidr)
		return
	}
	network := ipNet.IP.To4()
	if network == nil || !isUnicastIPv4(network) {
		add("subnetRouter.localNetworks: %q is not a unicast IPv4 network", cidr)
	}
	if ones == 0 {
		add("subnetRouter.localNetworks: default route is not allowed")
	}
}

func isUnicastIPv4(ip net.IP) bool {
	ip4 := ip.To4()
	if ip4 == nil {
		return false
	}
	switch {
	case ip4[0] == 0: // "this network"
		return false
	case ip4[0] == 127: // loopback
		return false
	case ip4[0] >= 224: // multicast, reserved, broadcast
		return false
	case ip4[0] == 169 && ip4[1] == 254: // link-local
		return false
	}
	return true
}

func validateDomainSuffix(s string) error {
	s = strings.TrimSpace(s)
	if s == "" {
		return fmt.Errorf("empty domain")
	}
	s = strings.TrimSuffix(s, ".")
	if len(s) > 253 {
		return fmt.Errorf("domain %q is too long", s)
	}
	labels := strings.Split(s, ".")
	for _, label := range labels {
		if label == "" || len(label) > 63 {
			return fmt.Errorf("invalid domain %q", s)
		}
		if strings.HasPrefix(label, "-") || strings.HasSuffix(label, "-") {
			return fmt.Errorf("invalid domain label %q", label)
		}
		for _, r := range label {
			if (r < 'a' || r > 'z') && (r < 'A' || r > 'Z') && (r < '0' || r > '9') && r != '-' && r != '_' && r != '*' {
				return fmt.Errorf("invalid character %q in domain %q", r, s)
			}
		}
	}
	return nil
}

func underAnyRoot(p string, roots []string) bool {
	clean := cleanPath(p)
	for _, root := range roots {
		root = cleanPath(root)
		if clean == root || strings.HasPrefix(clean, root+string(os.PathSeparator)) || strings.HasPrefix(clean, root+"/") {
			return true
		}
	}
	return false
}

func isAbsPath(p string) bool {
	if strings.HasPrefix(p, "/") {
		return true
	}
	if runtime.GOOS == "windows" {
		return filepath.IsAbs(p)
	}
	return path.IsAbs(p)
}

func cleanPath(p string) string {
	if runtime.GOOS == "windows" {
		return filepath.Clean(p)
	}
	return path.Clean(p)
}
